export type CommentAnchor={selector:string;x:number;y:number;pageKey:string};

// Only structural selectors generated by the annotation tool are accepted.
export function validCommentAnchor(value:unknown):value is CommentAnchor{
 if(!value||typeof value!=='object')return false;
 const anchor=value as CommentAnchor;
 return typeof anchor.selector==='string'&&anchor.selector.length<=2000&&/^\.shell(?: \[data-comment-target="[A-Za-z0-9:_-]{1,120}"\])?(?: > [a-z][a-z0-9-]*:nth-of-type\([1-9][0-9]*\))*$/.test(anchor.selector)&&typeof anchor.pageKey==='string'&&anchor.pageKey.length>0&&anchor.pageKey.length<=80&&[anchor.x,anchor.y].every(n=>typeof n==='number'&&Number.isFinite(n)&&n>=0&&n<=1);
}

export function anchorSelector(element:Element,root:Element):string|null{
 const parts:string[]=[];
 for(let current:Element|null=element;current&&current!==root;current=current.parentElement){
  const stable=current.getAttribute('data-comment-target');
  if(stable&&/^[A-Za-z0-9:_-]{1,120}$/.test(stable)&&root.contains(current))return `.shell [data-comment-target="${stable}"]`+(parts.length?' > '+parts.join(' > '):'');
  const parent=current.parentElement;if(!parent)return null;
  const siblings=Array.from(parent.children).filter(child=>child.tagName===current!.tagName);
  parts.unshift(`${current.tagName.toLowerCase()}:nth-of-type(${siblings.indexOf(current)+1})`);
  if(parent===root)return '.shell > '+parts.join(' > ');
 }
 return element===root?'.shell':null;
}

export function anchorPoint(anchor:CommentAnchor,rect:{left:number;top:number;width:number;height:number}){
 return {left:rect.left+rect.width*anchor.x,top:rect.top+rect.height*anchor.y};
}
